"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["63087"],{76795(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.permutacao_de_ordem_nao_suportada","status":422,"titulo":"A redefini\xe7\xe3o do cronograma troca a Ordem entre fases j\xe1 existentes formando um ciclo fechado, que n\xe3o pode ser persistido em uma \xfanica chamada"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.permutacao_de_ordem_nao_suportada","requisitos":[],"oQueAconteceu":["Na redefini\xe7\xe3o do cronograma, as fases que j\xe1 existiam continuam sendo as mesmas\\nfases (s\xe3o reconhecidas pela fase can\xf4nica de origem), e s\xf3 mudam de posi\xe7\xe3o pela\\n`ordem`. O pedido faz um ciclo fechado de trocas: a fase A assume a ordem da fase\\nB, que assume a da fase C, e assim at\xe9 uma fase assumir a ordem de A, de modo que\\nnenhuma ordem fica livre no caminho. A mensagem pede que uma das fases seja\\nmovida antes para uma ordem livre, em um pedido separado.","A cadeia aberta de trocas (a que termina numa ordem que ningu\xe9m ocupa, ou na de\\numa fase removida) \xe9 aceita; s\xf3 o ciclo fechado \xe9 recusado. A confer\xeancia vem\\ndepois das recusas das fases que saem ou mudam e da refer\xeancia ao fim da inscri\xe7\xe3o, e\\nantes da confer\xeancia das preced\xeancias entre fases. Nada \xe9 gravado."],"comoResolver":["Fa\xe7a a troca em duas redefini\xe7\xf5es: primeiro mova uma das fases do ciclo para uma\\nordem livre, e depois, em outro pedido, ponha as fases nas ordens finais."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);